import {ageAt} from './age.js';
import {ordinal} from './polish.js';
import {chatSuggestions} from './chat-personal.js';

const chatEscape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const doctorPortrait=()=>'<img src="assets/doktor-bielik.png" alt="" width="80" height="80" class="doctor-portrait">';
export const chatIcon=()=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 11a8 8 0 0 1-8 8H7l-5 3 2-6a8 8 0 1 1 16-5Z"/><path d="M8 10h8m-8 4h5"/></svg>';
const statusLabels={done:'Oznaczone jako wykonane','not-applicable':'Nie dotyczy',waiting:'Przed Wami',pending:'Do zrobienia',overdue:'Okres minął','needs-date':'Uzupełnij datę'};
function chatSourceUrl(value) {
  try{const url=new URL(value);if(url.protocol==='https:'&&!url.username&&!url.password&&['www.gov.pl','gov.pl','pacjent.gov.pl','www.zus.pl','zus.pl','www.nfz.gov.pl','akademia.nfz.gov.pl','www.pip.gov.pl','eli.gov.pl','dziennikmz.mz.gov.pl'].includes(url.hostname))return url.href;}catch{}
  return null;
}
const savedDate=value=>new Intl.DateTimeFormat('pl-PL',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Europe/Warsaw'}).format(new Date(value));
function sourceHtml(source){
  const url=chatSourceUrl(source.url);if(!url)return '';
  return `<a class="chat-source" href="${chatEscape(url)}" target="_blank" rel="noopener noreferrer"><span>${chatEscape(source.name)}</span><span aria-hidden="true">↗</span></a>${['changed','missing','unavailable'].includes(source.status)?'<p class="chat-source-note">To źródło wymaga ponownego sprawdzenia. Potwierdź aktualne zasady w instytucji.</p>':''}`;
}

export function renderBielikChat({profile,current,pending,error,notice,archive,historyOpen}) {
  const age=ageAt(profile.anchor),stage=`${ordinal(age.stage,'weeks')} ${profile.mode==='pregnancy'?'ciąży':'życia'}`;
  const messages=current.messages,examples=chatSuggestions(profile),saved=archive.conversations.find(c=>c.id===current.id);
  const header=`<header class="chat-header"><button id="chat-back" class="icon-button" aria-label="Wróć na moją drogę">‹</button><div class="chat-header-portrait">${doctorPortrait()}</div><div class="chat-header-title"><h2>Doktor Bielik</h2><p>Asystent AI · informacje, nie diagnoza</p></div><button id="chat-history" class="icon-button chat-history-toggle" title="Zapisane rozmowy" aria-label="Zapisane rozmowy" aria-expanded="${historyOpen}" ${pending?'disabled':''}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M3 7h18v13H3zM6 7V4h12v3M8 12h8m-8 4h5"/></svg><span>Rozmowy</span></button></header><div class="chat-context"><span class="chat-context-dot"></span>${chatEscape(stage)}</div><div class="chat-conversation-actions"><button id="chat-new" ${pending||!(messages.length||current.draft.trim())?'disabled':''}><span aria-hidden="true">＋</span>Nowa rozmowa</button><button id="chat-save" ${pending||!(messages.length||current.draft.trim())?'disabled':''}><svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M4 2h11l3 3v13H2V2h2Zm1 0v6h9V2M5 18v-6h10v6"/></svg>Zapisz rozmowę</button></div>${notice?`<p class="chat-save-status" role="status">${chatEscape(notice)}</p>`:''}`;
  if(historyOpen)return header+`<section class="chat-history-panel" aria-label="Zapisane rozmowy"><div class="chat-history-heading"><h3>Zapisane rozmowy</h3><button id="chat-history-back" class="text-button">Wróć do rozmowy</button></div><p>Rozmowy są zapisane w tej przeglądarce.</p>${error?`<p class="chat-error" role="alert">${chatEscape(error)}</p>`:''}${archive.conversations.length?archive.conversations.map(conversation=>`<div class="chat-history-row"><button data-open-chat="${conversation.id}"><strong>${chatEscape(conversation.title)}</strong><small>${chatEscape(savedDate(conversation.updatedAt))}</small></button><button data-delete-chat="${conversation.id}" class="chat-delete" aria-label="Usuń rozmowę: ${chatEscape(conversation.title)}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3M6 7l1 13h10l1-13M10 10v7m4-7v7"/></svg></button></div>`).join(''):'<div class="chat-history-empty">Nie masz jeszcze zapisanych rozmów. Użyj przycisku „Zapisz rozmowę” po wymianie wiadomości.</div>'}</section>`;
  return header+`<div class="chat-messages" role="log" aria-label="Rozmowa z Doktorem Bielikiem">${saved?`<p class="chat-session-stamp">Zapisana rozmowa · ${chatEscape(savedDate(saved.updatedAt))}</p>`:''}${!messages.length?`<div class="chat-welcome">${doctorPortrait()}<h3>Jestem obok, krok po kroku.</h3><p>Pomogę Ci sprawdzić, co załatwić, gdzie się zgłosić i o czym pamiętać w ciąży oraz na początkowym etapie życia dziecka.</p><div class="chat-suggestions">${examples.map((text,i)=>`<button data-chat-example="${i}">${chatEscape(text)}<span aria-hidden="true">↗</span></button>`).join('')}</div></div>`:''}${messages.map((message,index)=>`<article class="chat-message chat-message-${message.role}" data-chat-message="${index}"><span class="sr-only">${message.role==='user'?'Ty':'Doktor Bielik'}:</span><div class="chat-answer"></div>${message.sources?.length?`<div class="chat-sources"><h4>Oficjalne źródła odpowiedzi</h4>${message.sources.map(sourceHtml).join('')}</div>`:''}${message.tasks?.length?`<div class="chat-related"><span>Sprawy w aplikacji</span>${message.tasks.map(task=>`<button class="chat-task" data-chat-task="${chatEscape(task.id)}"><span><strong>${chatEscape(task.title)}</strong><small>${chatEscape(statusLabels[task.status]||'Zobacz kartę')}${task.period?` · ${chatEscape(task.period)}`:''}</small></span><span aria-hidden="true">›</span></button>`).join('')}</div>`:''}</article>`).join('')}${pending?`<div class="chat-thinking" role="status">${doctorPortrait()}<span>Obecnie pracuję nad rozwiązaniem powierzonego mi zagadnienia.</span></div>`:''}</div><div class="chat-bottom"><p class="chat-error" role="alert">${chatEscape(error)}</p><form id="chat-form"><label for="chat-input" class="sr-only">Twoje pytanie do Doktora Bielika</label><textarea id="chat-input" name="message" rows="1" maxlength="3000" placeholder="Zapytaj o Waszą drogę…" ${pending?'disabled':''}>${chatEscape(current.draft)}</textarea><button id="chat-send" type="submit" aria-label="Wyślij pytanie" ${pending?'disabled':''}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m5 12 7-7 7 7m-7-7v15"/></svg></button></form></div>`;
}
